ant -quiet test.javacCurrent > build/utilityclass-baseline-test.log 2>&1; result=$?; grep -A26 -B4 -E 'UtilityClassGeneric|NullPointerException|BUILD FAILED|Tests run:' build/utilityclass-baseline-test.log; exit "$result"

patch -p0 <<'PATCH'
--- src/core/lombok/javac/handlers/HandleUtilityClass.java
+++ src/core/lombok/javac/handlers/HandleUtilityClass.java
@@ -130,6 +130,10 @@
 				ClassSymbol innerClassSymbol = innerClassDecl.sym;
 				if (innerClassSymbol != null && innerClassSymbol.type instanceof ClassType) {
 					((ClassType) innerClassSymbol.type).setEnclosingType(Type.noType);
+					// javac may have cached the erasure before we made this class static.
+					if (innerClassSymbol.erasure_field instanceof ClassType) {
+						((ClassType) innerClassSymbol.erasure_field).setEnclosingType(Type.noType);
+					}
 				}
 			}
 		}
--- doc/changelog.markdown
+++ doc/changelog.markdown
@@ -2,7 +2,7 @@
 ----------------

 ### v1.18.25 "Edgy Guinea Pig"
-* No new changes since the release of v1.18.24
+* BUGFIX: `@UtilityClass` with nested classes, generic methods, and overloaded methods could cause javac to crash with a `NullPointerException` on JDK11+.

 ### v1.18.24 (April 18th, 2022)
PATCH
ant test.compile test.javacCurrent > build/utilityclass-fixed-test.log 2>&1; result=$?; grep -E '\[ERR\]|\[FAIL\]|UtilityClassGeneric|BUILD (SUCCESSFUL|FAILED)|Total time:' build/utilityclass-fixed-test.log; if [ "$result" -ne 0 ]; then tail -65 build/utilityclass-fixed-test.log; fi; exit "$result"

javap -p 'jar:file:///testbed/lib/javac6/net.java.openjdk.custom-javac6.jar!/com/sun/tools/javac/code/Symbol.class' | grep -E 'class |erasure'; patch -p0 <<'PATCH'
--- src/stubs/com/sun/tools/javac/code/Symbol.java
+++ src/stubs/com/sun/tools/javac/code/Symbol.java
@@ -23,6 +23,7 @@

 public abstract class Symbol implements Element {
 	public Type type;
+	public Type erasure_field;
 	public Name name;
 	public Symbol owner;

PATCH
ant test.compile test.javacCurrent > build/utilityclass-fixed-test.log 2>&1; result=$?; grep -E '\[ERR\]|\[FAIL\]|UtilityClassGeneric|BUILD (SUCCESSFUL|FAILED)|Total time:' build/utilityclass-fixed-test.log; if [ "$result" -ne 0 ]; then tail -65 build/utilityclass-fixed-test.log; fi; exit "$result"

patch -p0 <<'PATCH'
--- /dev/null
+++ build/UtilityClassTestRunner.java
@@ -0,0 +1,12 @@
+import java.io.File;
+import lombok.RunTestsViaEcj;
+import lombok.transform.TestWithEcj;
+
+public class UtilityClassTestRunner {
+	public static void main(String[] args) throws Throwable {
+		TestWithEcj params = new TestWithEcj();
+		File file = new File(params.getBeforeDirectory(), "UtilityClassGeneric.java");
+		new RunTestsViaEcj().createTester(params, file, "ecj", 8).runTest();
+		System.out.println("ECJ UtilityClassGeneric regression passed");
+	}
+}
PATCH
java -javaagent:dist/lombok.jar -Ddelombok.bootclasspath=/testbed/lib/openjdk8_rt.jar --class-path 'build/lombok-deps:build/lombok-main:build/lombok-utils:build/lombok-utils6:build/tests:build/teststubs:lib/build/*:lib/eclipse-oxygen/*:lib/test/*' build/UtilityClassTestRunner.java; result=$?; rm -f build/UtilityClassTestRunner.java; exit "$result"

